input.command:
cd /w; python3 - <<'EOF'
import json,re,collections
n=json.load(open('notes.json'))
lines=collections.Counter()
for x in n:
    for l in x['text'].split('\n'):
        l=l.strip()
        if l: lines[re.sub(r'\d+','#',l)]+=1
for k,v in lines.most_common(200): print(v,'|',k[:150])
EOF

