import numpy as np,json,collections
res=json.load(open('ecgres3.json'))
e=json.load(open('ecgs.json'))['ecgs']
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
alive={k for k,v in pats.items() if not v.get('deceasedDateTime')}
by=collections.defaultdict(list)
for x in e: by[x['patient']].append(x)
th=np.radians([0,60,120,-150,90,-30])  # I,II,III,aVR,aVF,aVL
def axis(M,on,off):
    a=np.array([M[on:off,i].sum() for i in [0,1,2,3,4,5]])
    x=(a*np.cos(th)).sum()/3; y=(a*np.sin(th)).sum()/3
    return np.degrees(np.arctan2(y,x))
def cls(d):
    if -30<=d<=90: return 'NORMAL'
    if -90<=d<-30: return 'LEFT'
    if 90<d<=180: return 'RIGHT'
    return 'EXTREME'
for p,v in sorted(by.items()):
    if p not in alive: continue
    v.sort(key=lambda x:x['time'])
    for x in v[-2:]:
        r=res[x['ecg']]; M=np.load('ecg/%s.m3.npy'%x['ecg'])
        d=axis(M,r['on'],r['off'])
        print('%s %s %s  ax2=%7.1f axLS=%7.1f %s'%(p[:8],x['ecg'],x['time'][:10],r['axis_deg'],d,cls(d)))
EOF

