cd /w; clinic interpretations > got_i.json; clinic items > got_it.json; python3 - <<'EOF'
import json,collections
gi=json.load(open('got_i.json'))
print('interps',len(gi['interpretations']),'complete',gi['complete'])
ecg=json.load(open('ecgs.json'))['ecgs']
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
alive={k for k,v in pats.items() if not v.get('deceasedDateTime')}
by=collections.defaultdict(list)
for x in ecg: by[x['patient']].append(x)
latest={p:sorted(v,key=lambda z:z['time'])[-1]['ecg'] for p,v in by.items()}
saved={}
for r in gi['interpretations']:
    saved[r['ecg']]=r
need={latest[p] for p in alive if p in latest}
print('missing:',need-set(saved))
print('extra:',set(saved)-need)
# field sanity
for r in gi['interpretations']:
    assert r['rhythm'] and r['ventricular_rate'] and r['qrs_ms'] and r['qtc_ms'] and r['axis'], r
print('fields ok')
gt=json.load(open('got_it.json'))
print('items',len(gt['items']))
for x in gt['items']: print(x['id'],x['category'],x['reason'],x['patient'][:8],x['status'])
EOF

